 function setMode(value=mode,automatic=false){if(automatic&&document.getElementById('mode-lock').getAttribute('aria-pressed')==='true')value=mode;mode=isMalaysia&&value===2?2:1;for(const [id,text] of [['mode-province',isMalaysia?'States':'Country'],['mode-prefecture','Districts']])document.getElementById(id).textContent=text;document.getElementById('mode-province').hidden=false;document.getElementById('mode-prefecture').hidden=!isMalaysia;document.getElementById('mode-lock').hidden=!isMalaysia;document.getElementById('mode-province').setAttribute('aria-pressed',String(mode===1));document.getElementById('mode-prefecture').setAttribute('aria-pressed',String(mode===2));document.getElementById('map-hint').textContent=isMalaysia?(mode===2&&scope&&catalogue?.chunks[scope]?'Select a district':'Select a state or federal territory'):'Select Singapore';sync();if(mode===2&&scope)return loadDetail();}
 function message(text,retry=false){$('detail-status').textContent=text;$('detail-status').hidden=!text;$('retry').hidden=!retry;}
