 $('search').onkeydown=e=>{if(e.key==='Enter')$('search-results').querySelector('button')?.click();if(e.key==='Escape')$('search-results').hidden=true;};if(isMalaysia)$('province').onchange=()=>$('province').value?select(index.get($('province').value)):reset();$('selection-reset').onclick=()=>reset();$('tab-explore').onclick=()=>panel('explore');$('tab-layers').onclick=()=>panel('layers');$('retry').onclick=loadDetail;for(const id of ['province-layer','label-layer',...(isMalaysia?['second-layer']:[])])$(id).onchange=sync;
